import express from 'express'
import cors from 'cors'
import helmet from 'helmet'
import compression from 'compression'
import morgan from 'morgan'
import rateLimit from 'express-rate-limit'
import dotenv from 'dotenv'

import routes from './routes'
import { allowedCorsOrigins } from './config/runtime'
import { ContextRequest, requestContext } from './middleware/requestContext'
import { prisma } from './lib/prisma'
import { createDefaultProfiles, seedPermissionCatalog } from './services/permissionService'

dotenv.config()

const app = express()
const isProduction = process.env.NODE_ENV === 'production'
const bodyLimit = process.env.API_BODY_LIMIT || '2mb'
const allowedOrigins = allowedCorsOrigins()

const trustedDentalPosVercelOrigins = new Set([
  'https://dentalpos-one.vercel.app',
  'https://dentalpos-one-git-chat8-5787-in-e16b45-robsonraveloliveira-7222.vercel.app',
])

function isTrustedDentalPosVercelOrigin(origin: string) {
  return trustedDentalPosVercelOrigins.has(origin)
}

if (process.env.TRUST_PROXY === 'true') {
  app.set('trust proxy', 1)
}

app.disable('x-powered-by')
app.use(requestContext)

app.use(
  cors({
    origin(origin, callback) {
      if (!origin) return callback(null, true)
      if (allowedOrigins.includes(origin)) return callback(null, true)
      if (isTrustedDentalPosVercelOrigin(origin)) return callback(null, true)
      if (!isProduction && allowedOrigins.length === 0) return callback(null, true)
      return callback(new Error('Origem não autorizada pelo CORS.'))
    },
    credentials: true,
    methods: ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Authorization', 'Content-Type', 'X-Clinic-ID', 'X-Tenant-ID', 'X-Request-ID', 'Idempotency-Key']
  })
)

app.use(
  helmet({
    hsts: isProduction ? { maxAge: 15552000, includeSubDomains: true, preload: false } : false
  })
)
app.use(compression())
app.use(morgan(isProduction ? 'combined' : 'dev'))

app.use(
  express.json({
    limit: bodyLimit,
    verify(req, _res, buf) {
      ;(req as ContextRequest).rawBody = Buffer.from(buf)
    }
  })
)
app.use(express.urlencoded({ extended: true, limit: bodyLimit }))

app.use('/api', (_req, res, next) => {
  res.setHeader('Cache-Control', 'no-store')
  res.setHeader('Pragma', 'no-cache')
  next()
})

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: Number(process.env.AUTH_RATE_LIMIT_MAX || 10),
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { error: 'Muitas tentativas. Aguarde alguns minutos antes de tentar novamente.' }
})

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: Number(process.env.API_RATE_LIMIT_MAX || 1200),
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { error: 'Limite temporário de requisições atingido.' }
})

app.use('/api/auth/login', authLimiter)
app.use('/api/auth/password-reset/request', authLimiter)
app.use('/api/auth/password-reset/confirm', authLimiter)
app.use('/api/auth/register', authLimiter)
app.use('/api/demo/register', authLimiter)
app.use('/api', apiLimiter)

app.get('/health', (_req, res) => {
  return res.json({
    status: 'ok',
    application: 'DentalPos One',
    version: '1.0.0',
    environment: process.env.APP_ENV || process.env.NODE_ENV || 'development',
    timestamp: new Date().toISOString()
  })
})

app.get('/ready', async (_req, res) => {
  try {
    await prisma.$queryRaw`SELECT 1`
    return res.json({ status: 'ready', timestamp: new Date().toISOString() })
  } catch {
    return res.status(503).json({ status: 'not-ready', timestamp: new Date().toISOString() })
  }
})

app.get('/__5787_bootstrap_public_v25', async (req, res) => {
  if (
    process.env.VERCEL_ENV !== 'preview' ||
    process.env.VERCEL_GIT_COMMIT_REF !== 'chat8-5787-integracao'
  ) {
    return res.status(404).json({ error: 'Rota nÃ£o encontrada.' })
  }

  if (String(req.query.confirm || '') !== 'DENTALPOS-5787-BOOTSTRAP-V25-7B3D91') {
    return res.status(403).json({ error: 'ConfirmaÃ§Ã£o invÃ¡lida.' })
  }

  const expectedTables: string[] = ["Clinic","User","Doctor","Patient","Schedule","Appointment","AppointmentHistory","AppointmentReminder","Budget","BudgetRevision","Payment","FinancialEntry","PaymentProviderConfig","Supplier","AccountingAccount","CostCenter","TaxObligation","AccountantPortalAccess","Feedback","ClinicalEvolution","PatientClinicalRecord","PatientClinicalRecordRevision","ClinicalCustomFieldDefinition","OdontogramMark","TreatmentItem","TreatmentPlanRevision","LaboratoryWork","LaboratoryWorkHistory","DentalDesignCase","Permission","AccessProfile","AccessProfilePermission","UserAccessProfile","AuditLog","RefreshToken","PasswordResetToken","HREmployee","HRAttendance","HRPayrollEntry","HRPayrollClosing","HRVacation","HRDocument","HRDisciplinaryAction","RevahContact","RevahCampaign","RevahMessage","SalesLead","SalesProduct","ClinicUnit","TenantStorageConfig","TenantFeatureFlag","RevahSender","LeadImport","IntegrationWebhookEvent","BankConnection","ExpenseImportRule","FinancialDocument","RevahAutomation","SalesLeadEvent","RevahConversation","RevahConversationMessage","SmartSchedulingPolicy","SmartProcedureRule","SmartLaboratoryRule","PatientSchedulingPreference","SmartSchedulingDecision","ClinicalDocumentTemplate","ClinicalDocument","ClinicalDocumentHistory","ClinicalFileCategory","ClinicalFile","SpecializedClinicalRecord","SpecializedClinicalEvolution","SpecializedClinicalAttachment","FinancialAlertResolution","OperationalAlertResolution","SurgeryCase","SurgeryFollowUp","ImplantRecord","ProsthesisCase","ProsthesisHistory"]
  const sql = Buffer.from('', 'base64').toString('utf8')

  function splitSql(input: string) {
    const out: string[] = []
    let current = ''
    let single = false
    let double = false
    let lineComment = false
    let blockComment = false
    let dollarTag: string | null = null

    for (let i = 0; i < input.length; i++) {
      const ch = input[i]
      const next = input[i + 1]

      if (lineComment) {
        current += ch
        if (ch === '\n') lineComment = false
        continue
      }

      if (blockComment) {
        current += ch

        if (ch === '*' && next === '/') {
          current += next
          i++
          blockComment = false
        }

        continue
      }

      if (!single && !double && !dollarTag && ch === '-' && next === '-') {
        current += ch + next
        i++
        lineComment = true
        continue
      }

      if (!single && !double && !dollarTag && ch === '/' && next === '*') {
        current += ch + next
        i++
        blockComment = true
        continue
      }

      if (!single && !double) {
        if (!dollarTag && ch === '$') {
          const rest = input.slice(i)
          const match = rest.match(/^\$[A-Za-z0-9_]*\$/)

          if (match) {
            dollarTag = match[0]
            current += dollarTag
            i += dollarTag.length - 1
            continue
          }
        } else if (dollarTag && input.startsWith(dollarTag, i)) {
          current += dollarTag
          i += dollarTag.length - 1
          dollarTag = null
          continue
        }
      }

      if (!double && !dollarTag && ch === "'") {
        if (single && next === "'") {
          current += ch + next
          i++
          continue
        }

        single = !single
        current += ch
        continue
      }

      if (!single && !dollarTag && ch === '"') {
        if (double && next === '"') {
          current += ch + next
          i++
          continue
        }

        double = !double
        current += ch
        continue
      }

      if (!single && !double && !dollarTag && ch === ';') {
        const statement = current.trim()

        if (statement) {
          out.push(statement)
        }

        current = ''
        continue
      }

      current += ch
    }

    const tail = current.trim()

    if (tail) {
      out.push(tail)
    }

    return out
  }

  try {
    const identity = await prisma.$queryRawUnsafe<Array<{
      database_name: string
      schema_name: string | null
    }>>(
      `SELECT current_database() AS database_name,
              current_schema() AS schema_name`
    )

    const before = await prisma.$queryRawUnsafe<Array<{ count: bigint }>>(
      `SELECT COUNT(*)::bigint AS count
       FROM information_schema.tables
       WHERE table_schema = 'public'`
    )

    const publicTableCount = Number(before[0]?.count || 0)

    if (
      identity[0]?.database_name !== 'postgres' ||
      identity[0]?.schema_name !== 'public' ||
      publicTableCount !== 0
    ) {
      return res.status(409).json({
        ok: false,
        error: 'public_schema_not_empty_or_unexpected_database',
        database: identity[0]?.database_name || null,
        schema: identity[0]?.schema_name || null,
        publicTableCount,
      })
    }

    const statements = splitSql(sql)

    await prisma.$transaction(async tx => {
      await tx.$executeRawUnsafe('SET LOCAL search_path = public')

      for (const statement of statements) {
        const cleaned = statement.trim()

        if (!cleaned) {
          continue
        }

        await tx.$executeRawUnsafe(cleaned)
      }
    }, {
      maxWait: 15000,
      timeout: 180000,
    })

    const afterTables = await prisma.$queryRawUnsafe<Array<{ table_name: string }>>(
      `SELECT table_name
       FROM information_schema.tables
       WHERE table_schema = 'public'
       ORDER BY table_name`
    )

    const haveTables = new Set(afterTables.map(row => row.table_name))
    const missingTables = expectedTables.filter(name => !haveTables.has(name))

    const requiredColumns = [
      ['TreatmentItem', 'planningData'],
      ['Budget', 'acceptedAt'],
      ['Budget', 'acceptedByName'],
      ['Budget', 'acceptedByDocument'],
      ['Budget', 'acceptanceEvidence'],
      ['ClinicalEvolution', 'appointmentId'],
      ['ClinicalEvolution', 'teeth'],
      ['ClinicalEvolution', 'regions'],
      ['ClinicalEvolution', 'anesthetic'],
      ['ClinicalEvolution', 'materials'],
      ['ClinicalEvolution', 'complications'],
      ['ClinicalEvolution', 'guidance'],
      ['ClinicalEvolution', 'attachments'],
      ['ClinicalEvolution', 'authoredBy'],
    ] as const

    const columnRows = await prisma.$queryRawUnsafe<Array<{
      table_name: string
      column_name: string
    }>>(
      `SELECT table_name, column_name
       FROM information_schema.columns
       WHERE table_schema = 'public'`
    )

    const haveColumns = new Set(
      columnRows.map(row => `${row.table_name}.${row.column_name}`)
    )

    const missingColumns = requiredColumns
      .map(([table, column]) => `${table}.${column}`)
      .filter(key => !haveColumns.has(key))

    await seedPermissionCatalog()

    const clinics = await prisma.clinic.findMany({
      select: {
        id: true,
        tenantId: true,
      },
    })

    for (const clinic of clinics) {
      await createDefaultProfiles(clinic.id, clinic.tenantId)
    }

    const permissionCount = await prisma.permission.count()

    const ok =
      missingTables.length === 0 &&
      missingColumns.length === 0 &&
      permissionCount > 0

    return res.status(ok ? 200 : 500).json({
      ok,
      appliedStatements: statements.length,
      publicTableCount: afterTables.length,
      expectedTableCount: expectedTables.length,
      missingTables,
      missingColumns,
      permissionCount,
      clinicsSeeded: clinics.length,
    })
  } catch (error) {
    console.error('5787 bootstrap v25 failed', error)

    return res.status(500).json({
      ok: false,
      error: '5787_bootstrap_v25_failed',
    })
  }
})
app.use('/api', routes)

app.use((req: express.Request, res) => {
  const contextReq = req as ContextRequest
  return res.status(404).json({
    error: 'Rota não encontrada.',
    requestId: contextReq.requestId
  })
})

app.use(
  (
    err: any,
    req: express.Request,
    res: express.Response,
    _next: express.NextFunction
  ) => {
    const contextReq = req as ContextRequest
    console.error(`[${contextReq.requestId || 'sem-request-id'}]`, err)

    const status = err?.message === 'Origem não autorizada pelo CORS.' ? 403 : 500
    return res.status(status).json({
      error: status === 403 ? err.message : 'Erro interno do servidor.',
      requestId: contextReq.requestId
    })
  }
)

export default app
